import org.json.*;import java.net.*;import java.io.*;class Client{static class Store{static final int PORT=47200;} static JSONObject call(JSONObject peer,JSONObject b)throws Exception{if(peer==null)throw new IOException("Peer no longer paired");HttpURLConnection c=(HttpURLConnection)new URL("http://"+peer.getString("ip")+":"+peer.optInt("port",Store.PORT)+"/recall").openConnection();c.setConnectTimeout(5000);c.setReadTimeout(8000);c.setRequestMethod("POST");c.setDoOutput(true);byte[] body=b.toString().getBytes("UTF-8");c.setFixedLengthStreamingMode(body.length);try{try(OutputStream out=c.getOutputStream()){out.write(body);}int status=c.getResponseCode();if(status!=200)throw new IOException("Recall HTTP "+status);ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(InputStream in=c.getInputStream()){byte[] chunk=new byte[256];int n;while((n=in.read(chunk))>0){bytes.write(chunk,0,n);if(bytes.size()>4096)throw new IOException();}}return new JSONObject(bytes.toString("UTF-8"));}finally{c.disconnect();}}}